// Temps relatif ("il y a 8 h" / "hace 8 h" / "8h ago") formaté par Intl dans la
// langue active : aucun libellé à maintenir à la main, et toute nouvelle
// langue ajoutée à LangContext fonctionne directement.
// Partagé par TheatersDrawer et TheaterPage.
export function formatRelativeTime(isoDate, lang) {
  const ts = new Date(isoDate).getTime();
  if (!isoDate || Number.isNaN(ts)) return "";
  const rtf = new Intl.RelativeTimeFormat(lang, { numeric: "auto", style: "narrow" });
  const diffSec = Math.round((ts - Date.now()) / 1000);
  const abs = Math.abs(diffSec);
  if (abs < 60) return rtf.format(0, "second");
  if (abs < 3600) return rtf.format(Math.round(diffSec / 60), "minute");
  if (abs < 86400) return rtf.format(Math.round(diffSec / 3600), "hour");
  if (abs < 86400 * 30) return rtf.format(Math.round(diffSec / 86400), "day");
  return rtf.format(Math.round(diffSec / (86400 * 30)), "month");
}